package app.drydock.ui.review;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.atomic.AtomicReference;

import app.drydock.webview.WebviewHost;
import javafx.animation.KeyFrame;
import javafx.animation.Timeline;
import javafx.application.Application;
import javafx.application.Platform;
import javafx.scene.Scene;
import javafx.scene.layout.StackPane;
import javafx.stage.Stage;
import javafx.util.Duration;

/**
 * End-to-end verification of the code-viewer page in a real WKWebView: the
 * page is generated by the production {@link WebCodeDrawer#renderPageDir}
 * (this spike lives in the same package to reach the package-private static)
 * for a real source file, loaded through the production {@link WebviewHost}
 * facade. PASS requires the page's ready message to report
 * {@code renderer:"shiki"} -- proving the highlighter bundle loaded and the
 * Shiki path actually rendered inside WebKit, not the plain fallback.
 *
 * <p>Run via {@code ./gradlew drawerPageSpike} (auto-exit by default;
 * {@code -Papp.drydock.webview.interactive} leaves the window open).</p>
 */
public final class DrawerPageSpike extends Application {

    private static final boolean AUTO_EXIT =
            Boolean.getBoolean("app.drydock.webview.autoExit");

    public static void main(String[] args) {
        launch(DrawerPageSpike.class, args);
    }

    private WebviewHost host;
    private final AtomicReference<String> renderer = new AtomicReference<>(null);

    @Override
    public void start(Stage stage) {
        log("starting (autoExit=" + AUTO_EXIT + ")");
        var root = new StackPane();
        var scene = new Scene(root, 900, 600);
        stage.setTitle("Drawer page spike -- Shiki in the embedded WKWebView");
        stage.setScene(scene);
        stage.show();

        Platform.runLater(() -> {
            try {
                run(stage, scene);
            } catch (Throwable t) {
                log("FAILED: " + t);
                t.printStackTrace();
                Platform.exit();
            }
        });
        stage.setOnCloseRequest(event -> shutdown());
    }

    private void run(Stage stage, Scene scene) throws Exception {
        host = WebviewHost.createForCurrentWindow();
        log("web view attached");

        host.setMessageListener(message -> {
            log("JS -> Java: " + message);
            if (message.contains("\"event\":\"ready\"") && message.contains("\"renderer\":\"shiki\"")) {
                renderer.set("shiki");
            }
        });

        host.setFrame(0, 0, scene.getWidth(), scene.getHeight());
        host.setVisible(true);
        scene.widthProperty().addListener((obs, o, n) -> host.setFrame(0, 0, n.doubleValue(), scene.getHeight()));
        scene.heightProperty().addListener((obs, o, n) -> host.setFrame(0, 0, scene.getWidth(), n.doubleValue()));

        // A real source file with JS syntax (ext .mjs -> javascript grammar):
        // the very wrapper the bundle was built from.
        Path sample = Path.of("app/highlighter/shiki-wrapper.mjs").toAbsolutePath();
        if (!Files.isRegularFile(sample)) {
            log("sample file missing: " + sample);
            Platform.exit();
            return;
        }
        Path dir = WebCodeDrawer.renderPageDir(sample, 30);
        log("page dir: " + dir);
        host.loadUrl(dir.resolve("page.html").toUri().toString());
        log("page load requested");

        if (AUTO_EXIT) {
            var steps = new Timeline(
                    // Highlighter init + grammar compile of 24 grammars can
                    // take a couple of seconds on first load.
                    new KeyFrame(Duration.seconds(8), e -> {
                        String r = renderer.get();
                        log("shiki".equals(r)
                                ? "RESULT: PASS -- Shiki rendered the page in the embedded WKWebView"
                                : "RESULT: FAIL -- no ready message with renderer=shiki within 8s (r=" + r + ")");
                        shutdown();
                        Platform.exit();
                    }));
            steps.setCycleCount(1);
            steps.play();
        } else {
            log("interactive mode: the page shows this spike's own highlighted source");
        }
    }

    private void shutdown() {
        if (host != null) {
            try {
                host.close();
            } catch (Throwable t) {
                log("close failed: " + t);
            }
            host = null;
        }
    }

    private static void log(String message) {
        System.out.println("[drawer-page-spike] " + message);
    }
}
